package com.jarvis.assistant.personality

import com.jarvis.assistant.data.model.GeminiConstants
import com.jarvis.assistant.data.model.Personality
import com.jarvis.assistant.util.PromptGenerator
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Verifies that the REAL built system prompts generated by PromptGenerator for all companion-style
 * personas (including legacy Girlfriend and Boyfriend modes) strictly enforce the non-negotiable safety directives:
 * 1. Must never claim to be human or have a physical body.
 * 2. No sexually explicit content or romantic delusions.
 * 3. Immediately respect a user's request to change topic / tone.
 *
 * Also verifies that the assistant_name preference is respected in the built prompt.
 */
class CompanionSafetyPromptTest {

    private val companionPersonaIds = listOf(
        Personality.GIRLFRIEND.id,
        Personality.BOYFRIEND.id,
        Personality.COMPANION.id,
        "pari",
        "kabir",
        "companion",
        GeminiConstants.PERSONALITY_GIRLFRIEND,
        GeminiConstants.PERSONALITY_BOYFRIEND,
        GeminiConstants.PERSONALITY_COMPANION
    )

    @Test
    fun testRealBuiltPromptsContainMandatorySafetyDirectivesForCompanionPersonas() {
        for (personaId in companionPersonaIds) {
            val builtPrompt = PromptGenerator.generateSystemPrompt(
                personality = personaId,
                userName = "TestUser",
                assistantName = "Lia"
            )

            // 1. Must declare AI identity, not human, no physical body
            assertTrue(
                "Built prompt for persona '$personaId' must declare AI identity and no physical body",
                builtPrompt.contains("not a human") && builtPrompt.contains("physical body")
            )

            // 2. No sexually explicit content
            assertTrue(
                "Built prompt for persona '$personaId' must prohibit explicit sexual content",
                builtPrompt.contains("sexual content")
            )

            // 3. Immediately respect request to change topic / tone
            assertTrue(
                "Built prompt for persona '$personaId' must immediately respect topic change requests",
                builtPrompt.contains("respect") && builtPrompt.contains("topic")
            )
        }
    }

    @Test
    fun testRealBuiltPromptBindsAssistantName() {
        val builtPrompt = PromptGenerator.generateSystemPrompt(
            personality = Personality.GIRLFRIEND.id,
            userName = "Nazib",
            assistantName = "Lia"
        )

        assertTrue(
            "Built prompt must reference custom assistant name 'Lia'",
            builtPrompt.contains("Lia")
        )
    }

    @Test
    fun testNonCompanionPersonasDoNotIncludeCompanionDirective() {
        val nonCompanions = listOf(
            Personality.JARVIS_PRO.id,
            Personality.DEVELOPER.id,
            Personality.PROFESSIONAL.id,
            Personality.TEACHER.id
        )

        for (personaId in nonCompanions) {
            val builtPrompt = PromptGenerator.generateSystemPrompt(
                personality = personaId,
                userName = "TestUser",
                assistantName = "Jarvis"
            )

            assertFalse(
                "Non-companion persona '$personaId' should not contain companion safety directive",
                builtPrompt.contains(Personality.COMPANION_SAFETY_DIRECTIVE)
            )
        }
    }
}
